initJs:
function(container, apiUrl, tables) {
  const tbody = container.querySelector("#work-history-tbody");

  // 1. テーブル再描画関数を定義
  async function renderRows(workRecords) {
    // 中断記録を取得して中断回数を計算
    const interruptRecords = await window.aivicApi.list(2) || [];

    tbody.innerHTML = workRecords.map(record => {
      const startTime = record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
      const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
      const workDate = record.作業日 ? new Date(record.作業日).toLocaleDateString('ja-JP') : '';
      const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}h${record.作業時間 % 60}m` : '';

      // この作業記録の中断回数を計算
      const interruptCount = interruptRecords.filter(interrupt => interrupt.作業記録ID === record.作業記録ID).length;

      // 進捗状況のスタイル
      let statusStyle = '';
      if (record.進捗状況 === '完了') {
        statusStyle = 'background: rgba(34, 197, 94, 0.1); color: #22c55e; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      } else if (record.進捗状況 === '作業中') {
        statusStyle = 'background: rgba(59, 130, 246, 0.1); color: #3b82f6; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      } else if (record.進捗状況 === '中断') {
        statusStyle = 'background: rgba(239, 68, 68, 0.1); color: #ef4444; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      }

      return `
        <tr data-id="${record.作業記録ID || ''}" style="cursor: pointer;">
          <td>${workDate}</td>
          <td>${record.作業種別 || ''}</td>
          <td>${startTime}</td>
          <td>${endTime}</td>
          <td>${workTime}</td>
          <td style="text-align: center;">${interruptCount}</td>
          <td><span style="${statusStyle}">${record.進捗状況 || ''}</span></td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${record.作業記録ID || ''}">詳細確認</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 2. 初期データを即座に描画
  renderRows(tables[1]?.records || []);

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const dateFrom = container.querySelector("#filter-date-from").value;
    const dateTo = container.querySelector("#filter-date-to").value;
    const status = container.querySelector("#filter-status").value;

    const allRecords = await window.aivicApi.list(1);
    if (!allRecords) return;

    const filteredRecords = allRecords.filter(record => {
      let match = true;

      if (dateFrom && record.作業日) {
        const recordDate = new Date(record.作業日).toISOString().split('T')[0];
        if (recordDate < dateFrom) match = false;
      }

      if (dateTo && record.作業日) {
        const recordDate = new Date(record.作業日).toISOString().split('T')[0];
        if (recordDate > dateTo) match = false;
      }

      if (status && record.進捗状況 !== status) match = false;

      return match;
    });

    renderRows(filteredRecords);
  });

  // 4. リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", async () => {
    container.querySelector("#filter-date-from").value = '';
    container.querySelector("#filter-date-to").value = '';
    container.querySelector("#filter-status").value = '';

    const allRecords = await window.aivicApi.list(1);
    if (allRecords) renderRows(allRecords);
  });

  // 5. CSVエクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const allRecords = await window.aivicApi.list(1);
    if (!allRecords) return;

    const interruptRecords = await window.aivicApi.list(2) || [];

    const csvData = [
      ['作業日時', '作業項目名', '開始時刻', '終了時刻', '作業時間(分)', '中断回数', '進捗状況', '作業場所', '作業内容']
    ];

    allRecords.forEach(record => {
      const interruptCount = interruptRecords.filter(interrupt => interrupt.作業記録ID === record.作業記録ID).length;
      csvData.push([
        record.作業日 ? new Date(record.作業日).toLocaleDateString('ja-JP') : '',
        record.作業種別 || '',
        record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleTimeString('ja-JP') : '',
        record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP') : '',
        record.作業時間 || '',
        interruptCount,
        record.進捗状況 || '',
        record.作業場所 || '',
        record.作業内容 || ''
      ]);
    });

    const csvContent = '\uFEFF' + csvData.map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `作業履歴一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 6. 画面遷移のイベントリスナー
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      window.showScreen("scr-1778907367889");
      return;
    }
  });

  container.querySelector("#btn-extract").addEventListener("click", () => {
    window.showScreen("scr-1778907353387");
  });

  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1778907133295");
  });

  // 初期データの再読み込み
  window.aivicApi.list(1).then(records => {
    if (records) renderRows(records);
  });
}
